const D = { energy: .6, scale: 1, speed: 1, density: .5, anneal: .5, hue: 205, x: .5, y: .5, style: 'pane', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Safety-glass shatter. Impact sites live on STAGGERED lifecycles:
//   nucleate -> radials creep out at finite speed -> Hertzian concentric rings fill in
//   behind the running tips -> the whole site slowly anneals away.
// Several sites overlap in time, so something is always growing and something always
// fading: no instant full-frame snap (anti-strobe) and no converged end state.
const u = Math.min(width, height);
const sd = P.seed | 0;
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };

// ---- the pane's backdrop: a soft out-of-focus scene so this reads as GLASS, not lines on
// black. Coarse buffer + upscale = free bokeh. Also carries the luminance floor. ----
const BW = 96, BH = Math.max(54, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) { S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; }
const tt = K.t;
const style = P.style;
// incommensurate drift — the backdrop alone can never re-phase over 8s
const dr1 = Math.sin(tt * 0.061), dr2 = Math.sin(tt * 0.143 + 1.7), dr3 = Math.sin(tt * 0.229 + 0.4);
const hb = ((P.hue % 360) + 360) % 360;
{
  const g = S.g; g.loadPixels(); const px = g.pixels;
  // 5 seeded bokeh blooms drifting behind the pane
  const NB = 5;
  const bx = [], by = [], br = [], bi = [];
  for (let k = 0; k < NB; k++) {
    bx[k] = (0.5 + 0.42 * Math.sin(tt * (0.037 + k * 0.011) + fr(k * 7 + 1) * 6.28)) * BW;
    by[k] = (0.5 + 0.40 * Math.cos(tt * (0.029 + k * 0.013) + fr(k * 7 + 2) * 6.28)) * BH;
    br[k] = (0.16 + 0.22 * fr(k * 7 + 3)) * BH;
    bi[k] = 0.30 + 0.55 * fr(k * 7 + 4);
  }
  for (let j = 0; j < BH; j++) {
    for (let i = 0; i < BW; i++) {
      let v = 0.10 + 0.16 * (1 - j / BH);                 // a dim ground gradient
      for (let k = 0; k < NB; k++) {
        const dx = i - bx[k], dy = j - by[k];
        const d = Math.sqrt(dx * dx + dy * dy) / br[k];
        if (d < 1) { const f = 1 - d * d; v += bi[k] * f * f * 0.9; }
      }
      v *= 0.62 + 0.5 * P.energy;
      const gr = (fr(i * 3.1 + j * 7.7 + 11) - 0.5) * 0.05;   // plate grain
      v = Math.max(0, Math.min(1, v + gr));
      let r, gg, b;
      if (style === 'ink') { const p2 = 0.87 - v * 0.46; r = p2 * 0.99; gg = p2 * 0.96; b = p2 * 0.88; }
      else if (style === 'xray') { r = 0.10 + v * 0.22; gg = 0.11 + v * 0.23; b = 0.13 + v * 0.26; }
      else if (style === 'frost') { r = 0.05 + v * 0.22; gg = 0.09 + v * 0.42; b = 0.20 + v * 0.62; }
      else if (style === 'tempered') { r = 0.09 + v * 0.52; gg = 0.12 + v * 0.60; b = 0.16 + v * 0.68; }
      else { // pane — cool laminated glass over a dim scene
        const hh = hb / 360;
        r = (0.06 + v * 0.55) * (0.55 + 0.45 * Math.cos(6.2831 * (hh + 0.02)));
        gg = (0.08 + v * 0.60) * (0.60 + 0.40 * Math.cos(6.2831 * (hh + 0.14)));
        b = (0.12 + v * 0.66) * (0.65 + 0.35 * Math.cos(6.2831 * (hh + 0.28)));
        r += 0.05; gg += 0.07; b += 0.11;
      }
      const o = 4 * (j * BW + i);
      px[o] = Math.max(0, Math.min(255, r * 255)); px[o + 1] = Math.max(0, Math.min(255, gg * 255));
      px[o + 2] = Math.max(0, Math.min(255, b * 255)); px[o + 3] = 255;
    }
  }
  g.updatePixels();
}

// ---- site bookkeeping: tolerate t0 resets (K.t can jump backwards at any time) ----
if (!S.sites || S.seedUsed !== P.seed || S.lastT == null || tt < S.lastT - 0.5) {
  S.seedUsed = P.seed; S.sites = []; S.next = tt; S.ctr = 0;
}
S.lastT = tt;
const LIFE = 26 + (1 - P.anneal) * 54;            // seconds from nucleation to fully annealed
const GAP = (2.6 + (1 - P.density) * 7.0) / Math.max(0.2, P.speed);
const MAXS = Math.round(2 + P.density * 8);
while (S.next <= tt && S.sites.length < MAXS + 3) {
  const c = S.ctr++;
  S.sites.push({
    t0: S.next, c: c,
    x: 0.12 + 0.76 * fr(c * 13.3 + 1), y: 0.12 + 0.76 * fr(c * 13.3 + 2),
    n: 7 + Math.floor(fr(c * 13.3 + 3) * 13),      // radial count
    r: 0.20 + 0.34 * fr(c * 13.3 + 4),             // final reach (fraction of u)
    sp: 0.55 + 0.9 * fr(c * 13.3 + 5)              // crack-tip speed
  });
  S.next += GAP * (0.55 + 0.9 * fr(c * 13.3 + 6));
}
S.sites = S.sites.filter(s => tt - s.t0 < LIFE);
if (S.next > tt + GAP * 4) S.next = tt;            // guard after a long tab-stall

// ---- draw ----
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(S.g, 0, 0, width, height);
pop();

const ctx = drawingContext;
const zoom = Math.max(1, P.scale);
const ax = P.x * width, ay = P.y * height;
ctx.save();
ctx.translate(ax, ay); ctx.scale(zoom, zoom); ctx.translate(-ax, -ay);
ctx.lineCap = 'round'; ctx.lineJoin = 'round';
const aa = Math.max(0, Math.min(100, P.alpha)) / 100;
// crack ink / specular colours per style
let INK, SPEC;
if (style === 'ink') { INK = [30, 24, 18]; SPEC = [250, 246, 232]; }
else if (style === 'xray') { INK = [232, 238, 248]; SPEC = [255, 255, 255]; }
else if (style === 'frost') { INK = [180, 232, 252]; SPEC = [236, 252, 255]; }
else if (style === 'tempered') { INK = [26, 34, 44]; SPEC = [226, 244, 255]; }
else { INK = [10, 14, 20]; SPEC = [214, 236, 255]; }

// jittered polyline from the impact centre outward — the crack tip wanders
function radial(sx, sy, ang, len, c, j, out) {
  const SEG = 7;
  let px2 = sx, py2 = sy, a = ang;
  out.push(sx, sy);
  for (let k = 1; k <= SEG; k++) {
    a += (fr(c * 91.7 + j * 17.3 + k * 3.1) - 0.5) * 0.30;
    const step = len / SEG;
    px2 += Math.cos(a) * step; py2 += Math.sin(a) * step;
    out.push(px2, py2);
  }
  return out;
}

for (const s of S.sites) {
  const age = tt - s.t0;
  if (age < 0) continue;
  const cx = s.x * width, cy = s.y * height;
  const reach = s.r * u;
  // crack tips run out over ~1.6-3s, NOT instantly. Ease so the tip decelerates (it arrests).
  const grow = Math.min(1, Math.pow(age * s.sp * P.speed * 0.42, 0.62));
  const L = reach * grow;
  if (L < u * 0.01) continue;
  // fade in over 0.9s, then anneal out over the tail of LIFE — no snap at either end
  const fin = Math.min(1, age / 0.9);
  const fout = Math.min(1, Math.max(0, (LIFE - age) / (LIFE * 0.55)));
  const op = fin * fout * (0.45 + 0.55 * P.energy) * aa;
  if (op < 0.012) continue;
  const nr = Math.max(4, Math.round(s.n * (0.45 + 0.55 * P.density)));

  // ---- radials ----
  const paths = [];
  for (let j = 0; j < nr; j++) {
    const ang = (j / nr) * 6.2831 + fr(s.c * 5.1 + j) * 0.5;
    // tips arrest at different lengths -> the ragged natural look
    const ll = L * (0.55 + 0.45 * fr(s.c * 3.7 + j * 2.3));
    paths.push(radial(cx, cy, ang, ll, s.c, j, []));
  }
  // shadow/ink pass
  ctx.beginPath();
  for (const p of paths) { ctx.moveTo(p[0], p[1]); for (let k = 2; k < p.length; k += 2) ctx.lineTo(p[k], p[k + 1]); }
  ctx.strokeStyle = 'rgba(' + INK[0] + ',' + INK[1] + ',' + INK[2] + ',' + (op * 0.85).toFixed(3) + ')';
  ctx.lineWidth = Math.max(0.7, u * 0.0026 * (0.6 + P.energy * 0.8)) / zoom;
  ctx.stroke();
  // specular edge pass — the bright lip that makes a crack read as glass
  ctx.beginPath();
  const off = u * 0.0016 / zoom;
  for (const p of paths) { ctx.moveTo(p[0] + off, p[1] - off); for (let k = 2; k < p.length; k += 2) ctx.lineTo(p[k] + off, p[k + 1] - off); }
  ctx.strokeStyle = 'rgba(' + SPEC[0] + ',' + SPEC[1] + ',' + SPEC[2] + ',' + (op * 0.5).toFixed(3) + ')';
  ctx.lineWidth = Math.max(0.4, u * 0.0011) / zoom;
  ctx.stroke();

  // ---- concentric Hertzian rings: only appear BEHIND the running tips ----
  if (style !== 'tempered') {
    const rings = 5;
    ctx.beginPath();
    let any = false;
    for (let q = 1; q <= rings; q++) {
      const rr = reach * (q / (rings + 0.6)) * (0.5 + 0.5 * fr(s.c + q * 9.1));
      if (rr > L * 0.86) continue;                 // the ring lags the radial tips
      any = true;
      for (let j = 0; j < nr; j++) {
        const a0 = (j / nr) * 6.2831 + fr(s.c * 5.1 + j) * 0.5;
        const a1 = ((j + 1) / nr) * 6.2831 + fr(s.c * 5.1 + j + 1) * 0.5;
        const x0 = cx + Math.cos(a0) * rr, y0 = cy + Math.sin(a0) * rr;
        const x1 = cx + Math.cos(a1) * rr, y1 = cy + Math.sin(a1) * rr;
        const am = (a0 + a1) * 0.5, bow = rr * (1.10 + 0.16 * fr(s.c + j * 3.3 + q));
        ctx.moveTo(x0, y0);
        ctx.quadraticCurveTo(cx + Math.cos(am) * bow, cy + Math.sin(am) * bow, x1, y1);
      }
    }
    if (any) {
      ctx.strokeStyle = 'rgba(' + INK[0] + ',' + INK[1] + ',' + INK[2] + ',' + (op * 0.6).toFixed(3) + ')';
      ctx.lineWidth = Math.max(0.5, u * 0.0016) / zoom; ctx.stroke();
    }
  } else {
    // tempered glass does not spider — it DICES into thousands of cubes. Fill the disc
    // with a stipple whose density rises as the dicing front sweeps out.
    ctx.beginPath();
    const nd = Math.round(260 * P.density + 90);
    for (let j = 0; j < nd; j++) {
      const a = fr(s.c * 2.7 + j * 1.7) * 6.2831;
      const rr = Math.sqrt(fr(s.c * 2.7 + j * 1.7 + 0.5)) * L;
      const dx = cx + Math.cos(a) * rr, dy = cy + Math.sin(a) * rr;
      const w = u * 0.005 * (0.5 + fr(j * 5.3 + s.c));
      ctx.moveTo(dx, dy); ctx.lineTo(dx + w, dy + w * 0.6);
    }
    ctx.strokeStyle = 'rgba(' + INK[0] + ',' + INK[1] + ',' + INK[2] + ',' + (op * 0.75).toFixed(3) + ')';
    ctx.lineWidth = Math.max(0.6, u * 0.0022) / zoom; ctx.stroke();
  }

  // ---- the crumb zone at the impact point: pulverised glass, brightest thing in frame ----
  const cz = u * 0.012 * (0.7 + 0.6 * fr(s.c + 3)) * Math.min(1, age * 1.4);
  ctx.beginPath(); ctx.arc(cx, cy, cz, 0, 6.2831);
  ctx.fillStyle = 'rgba(' + SPEC[0] + ',' + SPEC[1] + ',' + SPEC[2] + ',' + (op * 0.55).toFixed(3) + ')';
  ctx.fill();
  // a slow travelling glint: rides one radial, keeps the site alive to the eye
  const gi = (tt * 0.5 + s.c * 0.37) % 1;
  const ga = (Math.floor(tt * 0.21 + s.c) % nr) / nr * 6.2831;
  const gx = cx + Math.cos(ga) * L * gi, gy = cy + Math.sin(ga) * L * gi;
  ctx.beginPath(); ctx.arc(gx, gy, u * 0.006 * (1 - gi), 0, 6.2831);
  ctx.fillStyle = 'rgba(' + SPEC[0] + ',' + SPEC[1] + ',' + SPEC[2] + ',' + (op * 0.5 * (1 - gi)).toFixed(3) + ')';
  ctx.fill();
}
ctx.restore();

// ---- a wandering gallery reflection on the pane surface: ties the sites together,
// carries a guaranteed real-time motion floor, and lifts the mid-tone. ----
{
  const rx = (0.5 + 0.30 * dr1 + 0.12 * dr3) * width;
  const ry = (0.5 + 0.26 * dr2 + 0.10 * dr1) * height;
  const rr = u * (0.42 + 0.10 * dr3);
  const gd = ctx.createRadialGradient(rx, ry, 0, rx, ry, rr);
  const gi2 = (0.05 + 0.07 * P.energy) * aa;
  gd.addColorStop(0, 'rgba(255,255,255,' + gi2.toFixed(3) + ')');
  gd.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.save(); ctx.fillStyle = gd; ctx.fillRect(0, 0, width, height); ctx.restore();
}
blendMode(BLEND);
drawingContext.shadowBlur = 0;
